ALTER TABLE public.events ADD COLUMN agreements_locked boolean NOT NULL DEFAULT false;
UPDATE public.events SET agreements_locked=true WHERE status IN('published','cancelled');
CREATE OR REPLACE FUNCTION public.event_agreement_lock() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND OLD.agreements_locked THEN NEW.agreements_locked:=true;IF (NEW.host_id,NEW.team_id,NEW.requires_waiver,NEW.team_waiver_version) IS DISTINCT FROM(OLD.host_id,OLD.team_id,OLD.requires_waiver,OLD.team_waiver_version) THEN RAISE EXCEPTION 'waiver_pinned';END IF;END IF;IF NEW.status='published' THEN NEW.agreements_locked:=true;END IF;RETURN NEW;END $$;
CREATE TRIGGER events_agreement_lock BEFORE INSERT OR UPDATE ON public.events FOR EACH ROW EXECUTE FUNCTION public.event_agreement_lock();
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.attach_library_waiver(uuid,uuid,integer)'::regprocedure) INTO d;d:=replace(d,'IF e.status<>''draft'' THEN','IF e.status<>''draft'' OR e.agreements_locked THEN');EXECUTE d;SELECT pg_get_functiondef('public.host_waiver_event_guard()'::regprocedure) INTO d;d:=replace(d,'IF e.status<>''draft'' THEN','IF e.status<>''draft'' OR e.agreements_locked THEN');EXECUTE d;END $$;
DROP POLICY IF EXISTS "Event managers read waivers" ON public.event_waivers;CREATE POLICY host_read_event_waivers ON public.event_waivers FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM events e WHERE e.id=event_id AND e.host_id=auth.uid()));
DROP POLICY IF EXISTS "Event managers add waivers" ON public.event_waivers;CREATE POLICY host_add_event_waivers ON public.event_waivers FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM events e WHERE e.id=event_id AND e.host_id=auth.uid()));
DROP POLICY IF EXISTS "Event managers edit waivers" ON public.event_waivers;CREATE POLICY host_edit_event_waivers ON public.event_waivers FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM events e WHERE e.id=event_id AND e.host_id=auth.uid()));
DROP POLICY IF EXISTS "Event managers read waiver versions" ON public.event_waiver_versions;CREATE POLICY host_read_event_waiver_versions ON public.event_waiver_versions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM event_waivers w JOIN events e ON e.id=w.event_id WHERE w.id=waiver_id AND e.host_id=auth.uid()));
DROP POLICY IF EXISTS "Managers or the attendee read acceptances" ON public.event_waiver_acceptances;CREATE POLICY host_or_self_acceptances ON public.event_waiver_acceptances FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM events e WHERE e.id=event_id AND e.host_id=auth.uid()));
CREATE OR REPLACE FUNCTION public.host_waiver_cleanup_path(_path text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _path NOT LIKE auth.uid()::text||'/host-waivers/%.pdf' OR _path LIKE '%..%' THEN RETURN NULL; END IF;IF EXISTS(SELECT 1 FROM waiver_library_versions WHERE file_path=_path) OR EXISTS(SELECT 1 FROM event_waiver_versions WHERE file_path=_path) THEN RETURN NULL;END IF;RETURN _path;END $$;
REVOKE ALL ON FUNCTION public.host_waiver_cleanup_path(text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.host_waiver_cleanup_path(text) TO authenticated;
REVOKE ALL ON FUNCTION public.event_agreement_lock() FROM PUBLIC,anon,authenticated;